/**
 * The illustrations behind the heading of the section pages: a picture of the section's place, faded into the band (the
 * user, 28/10/2026, on marketing's brief). Decorative, generated by AI, which the band says beside it. Not on the home
 * page, which shows the news of the moment at once, nor on the others of SANS_FOND. On no page while Météo-France's
 * vigilance is orange or red, a cyclone alert is in force or announced, or the volcano is in alert: a calm picture would
 * contradict the source. Not written either when the browser asks to save data (`Save-Data: on`), nor on a page kept
 * out of the search engines (the secret page of a proposed event has the address of /associations/proposer). The
 * files: scripts/build-fonds.py.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import type { Alerte } from "./data.js";
import files from "./fonds.json" with { type: "json" };

