/** The pages whose picture is shown only while their own data says all is green: a calm sky above a storm would contradict it. */
const SEULEMENT_VERT = new Set(["/vigilance", "/cyclones", "/crues"]);

/**
 * Behind the band's text, over its upper 220 px (300 on wide screens), never adding height: framed on its upper third
 * on a phone, on its subject on wider screens, faded out by a mask, which works on any background. Dimmed so that the
 * band's light text keeps a contrast of at least 4.5:1 where the picture is brightest; more so under the top 3 rem, where
 * the breadcrumb's small grey text and the mention sit. The mention at the top right, like a photo credit, in the band's
 * brightest text. Not printed.
 */
export const FOND_CSS = `
.band>.fond{position:absolute;top:0;left:0;width:100%;height:220px;object-fit:cover;object-position:50% 25%;opacity:.35;pointer-events:none;
-webkit-mask-image:linear-gradient(to bottom,rgb(0 0 0/.6) 0,rgb(0 0 0/.6) 3rem,#000 5.5rem,rgb(0 0 0/.55) 45%,transparent 100%);mask-image:linear-gradient(to bottom,rgb(0 0 0/.6) 0,rgb(0 0 0/.6) 3rem,#000 5.5rem,rgb(0 0 0/.55) 45%,transparent 100%)}
@media (min-width:48rem){.band>.fond{height:300px;object-position:50% var(--y)}}
.fond-ia{position:absolute;top:.4rem;right:16px;margin:0;font-size:.75rem;line-height:1.2;color:var(--on-night)}
@media print{.band>.fond,.fond-ia{display:none}}
`.replace(/\n/g, "");

/** The brand kit's words, beside every picture made by AI. */
export const MENTION = "Illustration générée par IA";

/** Whether the request asks to save data, and whether a page built for it put or left out its picture for that reason. */
const sansFond = new AsyncLocalStorage<{ saveData: boolean; varie: boolean }>();

/**
 * Runs `fn` with the pages it builds left without their picture when `request` asks to save data. `varie`: a page it
 * built would have been otherwise with the other value of `Save-Data`, so that its response says `Vary: Save-Data`:
 * kept a minute by a shared cache (`public, max-age=60`), it would otherwise be served to a browser asking the other.
 */
export async function withSaveData<T>(request: Request, fn: () => T | Promise<T>): Promise<{ value: T; varie: boolean }> {
  const state = { saveData: request.headers.get("save-data")?.trim().toLowerCase() === "on", varie: false };
  const value = await sansFond.run(state, fn);
  return { value, varie: state.varie };
}

/** `r` with `Save-Data` added to its `Vary`, the values already there kept. */
export function varySaveData(r: Response): Response {
  const vary = r.headers.get("vary");
  if (vary && /(^|,)\s*(save-data|\*)\s*(,|$)/i.test(vary)) return r;
  const headers = new Headers(r.headers);
  headers.set("vary", vary ? `${vary}, Save-Data` : "Save-Data");
  return new Response(r.body, { status: r.status, statusText: r.statusText, headers });
}

/** Whether the vigilance or the volcano rules out every picture: orange or red, any cyclone alert, the volcano's alert. */
export const enAlerte = (alerte: Alerte | undefined, volcan: boolean): boolean => volcan || (!!alerte && ("cyclone" in alerte.court || alerte.couleur >= 3));

/**
 * The picture behind the band of the page at `path` and its mention, or nothing. On a phone, half its definition: the
 * picture is faded and dimmed, and the lighter file leaves the page's stylesheet and font their bandwidth. `vert`: the
 * page's own data says all is green (the pages of SEULEMENT_VERT).
 */
export function fond(path: string, alerte: Alerte | undefined, volcan: boolean, vert = false): string {
  const fond = FONDS[path];
  if (!fond || enAlerte(alerte, volcan) || (SEULEMENT_VERT.has(path) && !vert)) return "";
  // From here the picture depends on Save-Data alone: the response says so (withSaveData).
  const state = sansFond.getStore();
  if (state) state.varie = true;
  if (state?.saveData) return "";
  const f = files[fond.nom];
  return `<img class="fond" style="--y:${fond.y}%" src="/fonds/${f["480"]}" srcset="/fonds/${f["480"]} 480w, /fonds/${f["1024"]} 1024w" sizes="(min-width: 48rem) 100vw, 50vw" alt="" decoding="async" fetchpriority="low"><p class="fond-ia">${MENTION}</p>`;
}

/**
 * The contour lines of the island (marketing's kit, « Motif : les courbes de niveau »; ux's review of 04/11/2026), a
 * file of public/ whose address changes with its content. Only from 1200 px, where there is room beside the text: on a
 * narrower screen nothing is downloaded, a background picture under a media query being fetched only when it applies.
 * Night in both themes, like the band and the footer. Not in the HTML (an SVG hidden on a phone is paid for anyway) nor
 * as `data:` (the CSP refuses it, and it would weigh on the stylesheet that every page waits for).
 */
export const MOTIF_PATH = "/motif/ile-large.9aac573b5f.svg";

/**
 * The pages whose band shows the whole island beside its text from 1200 px, in place of its rays: the pages about the
 * site, the legal texts and the page of an address that does not exist (Head.motif), whose band holds neither data nor
 * picture and leaves its right free. Not /presse, whose visual takes that place.
 */
export const MOTIF_PAGES = new Set(["/a-propos", "/chiffres", "/valeurs", "/sources/transport", "/nouveautes", "/publier", "/ouvrir-ses-donnees", "/sites-sans-reponse", "/conditions", "/confidentialite"]);

/** The credit of the contour lines, in marketing's words, in the footer of every page that may show them. */
export const MOTIF_CREDIT = "Courbes de niveau du décor : IGN, RGE ALTI (Licence Ouverte 2.0).";

/**
 * Whether the page may show the contour lines: never while a picture is ruled out (enAlerte), nor when the browser asks
 * to save data; the page then says it varies with Save-Data, like fond().
 */
export function motif(alerte: Alerte | undefined, volcan: boolean): boolean {
  if (enAlerte(alerte, volcan)) return false;
  const state = sansFond.getStore();
  if (state) state.varie = true;
  return !state?.saveData;
}

/**
 * From 75rem (1200 px) only. In the band: the island at full strength in a box at the right of the content's column,
 * faded in from its left, never under the text (ux measured the contrast of the 10 pages at 6 widths in both themes,
 * none lower than today's). In the footer: only the room left free under its right column, which shrinks if the
 * sources grow, so never under text either. Neither printed nor shown with forced colours.
 */
export const MOTIF_CSS = `
@media (min-width:75rem){.band.motif::before{opacity:1;inset:0 max(0px,calc(50vw - 680px)) 0 auto;width:min(32vw,420px);background:url(${MOTIF_PATH}) no-repeat center/100% auto;-webkit-mask:linear-gradient(90deg,transparent,#000 12%);mask:linear-gradient(90deg,transparent,#000 12%)}
footer.foot.motif .wrap>div:last-child{display:flex;flex-direction:column}
footer.foot.motif .wrap>div:last-child::after{content:"";flex:1;margin-top:1.25rem;pointer-events:none;background:url(${MOTIF_PATH}) no-repeat 100% 42%/820px auto;-webkit-mask:linear-gradient(90deg,transparent,#000 40%);mask:linear-gradient(90deg,transparent,#000 40%)}}
@media print{.band.motif::before,footer.foot.motif .wrap>div:last-child::after{display:none}}
@media (forced-colors:active){.band.motif::before,footer.foot.motif .wrap>div:last-child::after{display:none}}
`.replaceAll("\n", "");
